def solve_with_hypergraph(n):
    from itertools import combinations

    def is_valid(subset):
        for x, y, z in combinations(subset, 3):
            if (x + y + z) % 2 == 0:
                sorted_xyz = sorted([x, y, z])
                if sorted_xyz[0] + sorted_xyz[1] > sorted_xyz[2]:
                    return False
        return True

    # Since it's a maximum independent set problem, let's use a more robust method.
    # However, for n=30, it might be too slow. Let's use a heuristic or a better approach.
    # We can use a simple backtracking with pruning.

    max_size = 0

    def backtrack(start_idx, current_subset):
        nonlocal max_size
        if len(current_subset) > max_size:
            max_size = len(current_subset)

        # Pruning: if the remaining elements cannot possibly beat max_size
        if len(current_subset) + (n - start_idx + 1) <= max_size:
            return

        for i in range(start_idx, n + 1):
            # Check if adding i violates the condition
            can_add = True
            for j in range(len(current_subset)):
                for k in range(j + 1, len(current_subset)):
                    x, y, z = current_subset[j], current_subset[k], i
                    if (x + y + z) % 2 == 0:
                        s_xyz = sorted([x, y, z])
                        if s_xyz[0] + s_xyz[1] > s_xyz[2]:
                            can_add = False
                            break
                if not can_add:
                    break

            if can_add:
                backtrack(i + 1, current_subset + [i])

    backtrack(1, [])
    return max_size

